<div class="d-flex gap-2 align-items-center mb-3"><h2 class="h4 mb-0"><?= e($ss['subject_name']) ?></h2><a class="btn btn-outline-secondary ms-auto" href="<?= url('learn') ?>"><i class="bi bi-arrow-right"></i> موادي</a></div>
<?php $vis = array_filter($live, fn($v) => \App\Services\LiveService::state($v) !== 'ended'); if ($vis): ?><div class="card-s mb-3"><h3 class="h6"><i class="bi bi-camera-video"></i> الحصص المباشرة</h3><?php foreach ($vis as $v): $stt = \App\Services\LiveService::state($v); $on = in_array($stt, ['live', 'soon'], true); ?>
  <div class="d-flex flex-wrap gap-2 align-items-center border-top py-2"><strong><?= e($v['title']) ?></strong><span class="badge text-bg-<?= ['live' => 'success', 'soon' => 'warning', 'upcoming' => 'secondary'][$stt] ?>"><?= ['live' => 'مباشر الآن', 'soon' => 'تبدأ قريبًا', 'upcoming' => 'قادمة'][$stt] ?></span><small dir="ltr" class="text-muted"><?= e(substr($v['starts_at'], 0, 16)) ?></small>
   <a class="btn btn-sm btn-<?= $on ? 'success' : 'outline-secondary' ?> ms-auto" href="<?= url('learn/live/' . (int)$v['id']) ?>"><?= $on ? 'انضم' : 'التفاصيل' ?></a></div><?php endforeach; ?></div><?php endif; ?>
<div class="row g-3"><div class="col-lg-4"><div class="card-s h-100"><h3 class="h6"><i class="bi bi-journal-text"></i> الدروس</h3><?php if (!$lessons): ?><div class="text-muted small">لا توجد دروس منشورة.</div><?php endif; ?><ul class="list-unstyled mb-0"><?php foreach ($lessons as $l): ?><li class="py-1"><a href="<?= url('learn/lessons/' . (int)$l['id']) ?>"><?= e($l['title']) ?></a> <?php if ((int)$l['materials']): ?><small class="text-muted"><i class="bi bi-paperclip"></i><?= (int)$l['materials'] ?></small><?php endif; ?></li><?php endforeach; ?></ul></div></div>
  <div class="col-lg-4"><div class="card-s h-100"><h3 class="h6"><i class="bi bi-clipboard-check"></i> الواجبات</h3><?php if (!$assignments): ?><div class="text-muted small">لا توجد واجبات.</div><?php endif; ?><?php foreach ($assignments as $a): $late = strtotime($a['due_at']) < time(); ?><div class="py-1 border-bottom"><a href="<?= url('learn/assignments/' . (int)$a['id']) ?>"><?= e($a['title']) ?></a><br><small class="text-muted" dir="ltr"><?= e($a['due_at']) ?></small>
    <?php if ($a['graded_at']): ?><span class="badge text-bg-success">الدرجة <?= (float)$a['score'] ?></span><?php elseif ($a['submission_id']): ?><span class="badge text-bg-info">سُلّم</span><?php elseif ($late): ?><span class="badge text-bg-danger">فات الموعد</span><?php else: ?><span class="badge text-bg-warning">مطلوب</span><?php endif; ?></div><?php endforeach; ?></div></div>
  <div class="col-lg-4"><div class="card-s h-100"><h3 class="h6"><i class="bi bi-ui-checks"></i> الاختبارات</h3><?php if (!$quizzes): ?><div class="text-muted small">لا توجد اختبارات.</div><?php endif; ?><?php foreach ($quizzes as $z): ?><div class="py-1 border-bottom"><a href="<?= url('learn/quizzes/' . (int)$z['id']) ?>"><?= e($z['title']) ?></a><br><small class="text-muted"><?= $z['duration_min'] ? (int)$z['duration_min'] . ' دقيقة — ' : '' ?>محاولاتك <?= (int)$z['my_attempts'] ?>/<?= (int)$z['max_attempts'] ?></small></div><?php endforeach; ?></div></div></div>
